package com.plantgrowth.forecasting.dto;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
public final class Contracts { private Contracts(){} public record Register(@NotBlank String fullName,@Email String email,@Size(min=8,max=100) String password){} public record Login(@Email String email,@NotBlank String password){} public record Auth(String accessToken,UserView user){} public record UserView(Long id,String fullName,String email,String role){} public record PlantInput(@NotBlank String plantCode,@NotBlank String plantName,String species,LocalDate plantingDate,@NotBlank String locationName){} public record PlantView(Long id,String plantCode,String plantName,String species,LocalDate plantingDate,String locationName,String imageUrl){} public record GrowthInput(@NotNull Instant measurementTimestamp,@NotNull @Positive Double plantHeightCm,@NotBlank String measurementMethod,@NotBlank String source){} public record GrowthView(Long id,Instant measurementTimestamp,Double plantHeightCm){} public record SoilInput(LocalDate observationDate,@DecimalMin("0.0") @DecimalMax("14.0") Double soilPh,@DecimalMin("0.0") @DecimalMax("100.0") Double soilMoisture,@DecimalMin("0.0") Double nitrogen,@DecimalMin("0.0") Double phosphorus,@DecimalMin("0.0") Double potassium,@NotBlank String source){} public record SoilView(Long id,LocalDate observationDate,Double soilPh,Double soilMoisture,Double nitrogen,Double phosphorus,Double potassium,String source){} public record ImageView(String imageUrl){} public record PredictionInput(@NotNull Long plantId,@NotBlank String targetType,@Min(1) @Max(365) int forecastHorizonDays,@NotBlank String modelName){} public record ActualInput(@NotNull @Positive Double actualFutureHeightCm){} public record PredictionView(Long id,Double currentHeightCm,Double predictedFutureHeightCm,Double predictedGrowthCm,Integer forecastHorizonDays,String modelName,String modelVersion,String dataQualityStatus,Object shapExplanation,List<Map<String,Object>> modelComparisonMetrics){} }
